return-response.set-body:
@{
            return new JObject(
              new JProperty("error", "Policy Violation: Role lacks permission"),
              new JProperty("agent", context.Variables["agentId"]),
              new JProperty("roles", context.Variables["userRoles"]),
              new JProperty("correlationId", context.Variables["correlationId"])
            ).ToString();
          }

when.set-body:
@{
          var body = context.Request.Body.As(preserveContent: true) ?? new JObject();
          var message = (string)(body["message"] ?? "");
          var agentId = context.Request.MatchedParameters.GetValueOrDefault("agentId", "triage-router-agent");
          var agentRef = new JObject(
            new JProperty("name", agentId),
            new JProperty("type", "agent_reference")
          );
          return new JObject(
            new JProperty("input", message),
            new JProperty("agent_reference", agentRef),
            new JProperty("metadata", new JObject(
              new JProperty("correlationId", (string)context.Variables["correlationId"]),
              new JProperty("userOid", (string)context.Variables["userOid"]),
              new JProperty("roles", (string)context.Variables["userRoles"])
            ))
          ).ToString();
        }

@{
          var raw = context.Response.Body.As(preserveContent: true) ?? new JObject();
          var agentId = context.Request.MatchedParameters.GetValueOrDefault("agentId", "");
          var content = (string)(raw["output_text"] ?? "");
          if (string.IsNullOrEmpty(content)) {
            // Fall back to first message output_text parts
            var output = raw["output"] as JArray;
            if (output != null) {
              var sb = new System.Text.StringBuilder();
              foreach (var item in output) {
                var blocks = item["content"] as JArray;
                if (blocks == null) { continue; }
                foreach (var block in blocks) {
                  var t = (string)(block["text"] ?? "");
                  if (!string.IsNullOrEmpty(t)) { sb.Append(t); }
                }
              }
              content = sb.ToString();
            }
          }
          if (string.IsNullOrEmpty(content)) {
            content = "Foundry agent returned no visible text.";
          }
          return new JObject(
            new JProperty("agent", agentId),
            new JProperty("harness", "microsoft_copilot_preview"),
            new JProperty("reply", content),
            new JProperty("output_markdown", content),
            new JProperty("correlationId", context.Variables["correlationId"]),
            new JProperty("model", raw["model"]),
            new JProperty("usage", raw["usage"]),
            new JProperty("trace", new JArray(
              new JObject(new JProperty("step", "apim_gateway"), new JProperty("status", "ok")),
              new JObject(new JProperty("step", "foundry_project"), new JProperty("status", "ok"), new JProperty("agent", agentId))
            ))
          ).ToString();
        }
